from pathlib import Path
from elftools.elf.elffile import ELFFile
import subprocess,json,hashlib
R=Path(__file__).resolve().parents[1]
names=['ANDROID_INFO_SUPPORTED_HARDWARE_LEVEL','ANDROID_INFO_SUPPORTED_HARDWARE_LEVEL_LIMITED','ANDROID_INFO_SUPPORTED_HARDWARE_LEVEL_LEGACY','ANDROID_REQUEST_AVAILABLE_CAPABILITIES','ANDROID_REQUEST_AVAILABLE_REQUEST_KEYS','ANDROID_REQUEST_AVAILABLE_RESULT_KEYS','ANDROID_REQUEST_AVAILABLE_CHARACTERISTICS_KEYS','ANDROID_SCALER_AVAILABLE_STREAM_CONFIGURATIONS','ANDROID_SCALER_AVAILABLE_MIN_FRAME_DURATIONS','ANDROID_SCALER_AVAILABLE_STALL_DURATIONS','ANDROID_CONTROL_AE_AVAILABLE_TARGET_FPS_RANGES','ANDROID_SENSOR_INFO_ACTIVE_ARRAY_SIZE','ANDROID_SENSOR_INFO_PIXEL_ARRAY_SIZE','ANDROID_SENSOR_INFO_PHYSICAL_SIZE','ANDROID_SENSOR_INFO_EXPOSURE_TIME_RANGE','ANDROID_SENSOR_ORIENTATION','ANDROID_LENS_FACING','ANDROID_JPEG_MAX_SIZE','ANDROID_LOGICAL_MULTI_CAMERA_PHYSICAL_IDS']
s='/* Schema witness only: generated enum header included alone to avoid unrelated ABI headers. No metadata values are manufactured. */\n#include "../inputs/sdk37_camera_metadata_tags.h"\n_Static_assert(ANDROID_INFO_SUPPORTED_HARDWARE_LEVEL_LIMITED == 0, "COMMON byte zero is LIMITED, not LEGACY");\n_Static_assert(ANDROID_LOGICAL_MULTI_CAMERA_PHYSICAL_IDS == 0x1a0000, "OEM private version tag must not be copied as an Android tag");\nconst unsigned int witnessed_tags[] = {\n'+',\n'.join(names)+'\n};\n'
p=R/'fixture/schema_witness.c';p.write_text(s);out=R/'fixture/schema_witness.arm32.o';cmd=['clang','--target=armv7a-none-eabi','-std=c11','-ffreestanding','-c',str(p),'-o',str(out)];q=subprocess.run(cmd,capture_output=True,text=True,check=True)
with out.open('rb') as f:
 e=ELFFile(f);sym=next(x for x in e.get_section_by_name('.symtab').iter_symbols() if x.name=='witnessed_tags');data=e.get_section(sym['st_shndx']).data()[sym['st_value']:sym['st_value']+sym['st_size']];values=[int.from_bytes(data[i:i+4],'little') for i in range(0,len(data),4)]
record={'compiler':subprocess.run(['clang','--version'],capture_output=True,text=True,check=True).stdout,'command':cmd,'stderr':q.stderr,'sha256':hashlib.sha256(out.read_bytes()).hexdigest(),'elfclass':32,'machine':'EM_ARM','qualification':'Compile-only SDK37 enum/schema witness, not OEM metadata data or runtime/ABI qualification','values':{n:{'decimal':v,'hex':hex(v)} for n,v in zip(names,values)}}
(R/'evidence/schema-witness.json').write_text(json.dumps(record,indent=2));print(json.dumps(record['values'],indent=2))
